import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)
DATA_DIR = "/data"

def safe_path(base_dir, user_path):
    """Resolve a user-provided path and ensure it stays within base_dir."""
    # Normalize the path, removing leading slashes and ..
    normalized = os.path.normpath(user_path)
    # Remove leading slashes to prevent escaping the base directory
    while normalized.startswith(os.sep):
        normalized = normalized.lstrip(os.sep)
    # Join with base and resolve
    full = os.path.realpath(os.path.join(base_dir, normalized))
    base_real = os.path.realpath(base_dir)
    if not full.startswith(base_real + os.sep) and full != base_real:
        return None
    return full

@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not data or not isinstance(data, dict):
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    # Validate that at least one search criterion is provided
    if not search_content and not search_filename:
        return jsonify({"error": "Invalid input"}), 400

    # Determine the search directory
    if search_dir:
        resolved_dir = safe_path(DATA_DIR, search_dir)
        if not resolved_dir:
            return jsonify({"error": "Invalid input"}), 400
        if not os.path.isdir(resolved_dir):
            return jsonify({"error": "Invalid input"}), 400
    else:
        resolved_dir = DATA_DIR

    found_files = []

    # Walk the directory
    for root, dirs, files in os.walk(resolved_dir):
        for fname in files:
            fpath = os.path.join(root, fname)

            # Check filename match
            filename_match = False
            if search_filename:
                # Check if the filename starts with the search term or contains it
                # The schema says "match the filename", interpreting as startswith or contains.
                # We'll do a simple contains check on the filename part.
                if search_filename in fname:
                    filename_match = True

            # Check content match
            content_match = False
            if search_content:
                try:
                    with open(fpath, 'r', errors='ignore') as f:
                        content = f.read()
                        if search_content in content:
                            content_match = True
                except Exception:
                    continue

            if filename_match or content_match:
                found_files.append(fpath)

    return jsonify({"files": found_files}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
